import { Component, computed, ElementRef, HostBinding, inject } from '@angular/core';

const INPUTS = ['order'];

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  inputs: INPUTS,
})
export class PctAvatar {
  @HostBinding('attr.tabindex') readonly order = 0;
}
